namespace Fanex.Age.UI.Reports.Monitor
{
    using System;
    using System.Collections.Generic;
    using System.Data;
    using System.Text;
    using System.Web;
    using System.Web.UI;
    using Fanex.BetList.Age.BetListHTMLBuilderExt;
    using Fanex.BetList.Age.DTO;
    using Fanex.BetList.Age.ExtTemplate;
    using Fanex.BetList.Core.Builder;
    using Fanex.BetList.Core.Entities;
    using Fanex.BetList.Core.Factories;
    using Fanex.BetList.Core.TicketHelper;
    using Fanex.Common;
    using Sunplus.Agent.Model.BL.Forecast;
    using Sunplus.Agent.Model.BL.Reports;
    using Sunplus.Agent.Model.Entities;
    using Fanex.Caching;
    using System.Collections;

    /// <summary>
    /// Bets list monitoring.
    /// </summary>
    public partial class MonitorBetList_Page : Reports_Page
    {
        private const int MinTimeAllowToWriteLog = 30;
        private static DateTime lastTimeWrittingExceptionLog = DateTime.Now;
        private readonly List<int> winplaceBetTypesId = new List<int> { 33, 1233 };
        private int betTypeGroup = 0, sportTypeGroup = 0, limitRowCount = 10;
        private long transId = 0;
        private string functionTurnOffError = string.Empty;

        public string TransIdCookieKey
        {
            get
            {
                string name = string.Join(null, new string[] { CurrentUserSession.CustId.ToString(), "lastTransId", CurrentUserSession.UserId.ToString() });
                return Sunplus.Agent.Utilities.Encryption.CfsEnCode(name, 6);
            }
        }

        /// <summary>
        /// Render content.
        /// </summary>
        /// <param name="writer"></param>
        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable bets = View as DataTable;
            Header1_Template betlistHeader = new Header1_Template();
            betlistHeader.Super.Hide();
            betlistHeader.Master.Hide();
            betlistHeader.Agent.Hide();
            betlistHeader.Winloss.Hide();

            StringBuilder content = new StringBuilder();
            Fanex.BetList.Age.ExtTemplate.OpenBetList_Template betlistOpenTag = new Fanex.BetList.Age.ExtTemplate.OpenBetList_Template();

            content.Append(betlistOpenTag);
            content.Append(betlistHeader);
            content.Append("<tbody>");

            bool isShowScoremap = true;
            bool isAdminCanViewVNIP = UserSession.Current.IsAdminCanViewVNIP;

            ITicketHelper ticketHelper = new TicketHelper();
            BetListHTMLFactory factory = new BetListHTMLFactory();
            BetListHTMLBuilder builder = factory.CreateBuilder();

            ForecastBO bo = new ForecastBO(UserSession.Current.NetSessionId);
            List<int> lstScoremap = bo.GetListBetTypeScoreMap();

            IList<ITicket> lastBetTickets = TicketTransformer.Transform(bets);
            bets.Dispose();

            int index = 0;
            GetCachePropertyById funcGetOddsTypeName = CacheRef.GetOddsTypeName;
            List<ITicketData> ticketData;

            var matchsInvalid = string.Empty;
            foreach (ITicket ticket in lastBetTickets)
            {
                //// we will write log if homeid = 0, awayid = 0, leagueid = 0, and sporttypeid = 0 and matchid is not mix-parlay and not is system parlay.
                if ((ticket.HomeId == 0 && ticket.AwayId == 0 && ticket.LeagueId == 0 && ticket.SportTypeId == 0) && ticket.MatchId != 9 && ticket.MatchId != 29)
                {
                    matchsInvalid += ticket.MatchId + ", ";
                }

                if (lstScoremap.Contains(ticket.BetTypeId))
                {
                    isShowScoremap = true;
                }
                else
                {
                    isShowScoremap = false;
                }

                index++;
                ticketHelper.Index = index;

                // Create reference data if current ticket is win/place ticket
                ticketData = CreateWinPlaceTicketData(ticket);

                builder.Append(string.Format("<tr id='r{0}'>", ticket.TransId))
                           .AddNo(index, "<td class='w-order'>", "</td>")
                           .AddMember(ticket, "<td class='c'>", "</td>")
                           .AddTrans(ticket, "<td class='c nonbreak'>", "</td>")
                           .AddChoice(ticket, ticketHelper, null, "<td class='r bl_evt'><div>", "</div></td>", isShowScoremap)
                           .AddOdds(ticket, ticketData, "<td class='bl_underdog nonbreak'>", "</td>", funcGetOddsTypeName)
                           .AddStake(ticket, "<td class='bl_underdog'>", "</td>")
                           .AddStatus(ticket, ticketHelper, null, "<td class='c'>", "</td>", isAdminCanViewVNIP)
                           .Append("</tr>");
            }

            if ((DateTime.Now - lastTimeWrittingExceptionLog).TotalSeconds >= MinTimeAllowToWriteLog && !string.IsNullOrEmpty(matchsInvalid))
            {
                lastTimeWrittingExceptionLog = DateTime.Now;
                Fanex.Logging.LogService.Critical(string.Format("The info of match(s) ({0}) is/are null!", matchsInvalid), "Agent-LastBetMonitoring");
            }

            builder.AddFooter(lastBetTickets, string.Empty, string.Empty, Sunplus.Agent.Model.BL.Definitions.UserTypes.Member, Fanex.BetList.Age.Definition.BetListType.Member);

            content.Append(builder.GetBetList());
            content.Append("</tbody></table>");

            writer.Write(content.ToString());
        }

        public override void ProcessRequest(ref System.Collections.Hashtable p)
        {
            functionTurnOffError = string.Format("FUNCTIONISTURNOFF_{0}", Resources.Lang.FunctionTurnOffError);

            if (!CheckingLastsBetMonitoringFunctionStatus())
            {
                Response.Write(functionTurnOffError);
                Response.End();
            }

            int.TryParse(this.Request["sportTypeGroup"], out this.sportTypeGroup);
            int.TryParse(this.Request["betTypeGroup"], out this.betTypeGroup);
            int.TryParse(this.Request["limitRowCount"], out this.limitRowCount);

            long.TryParse(Request.Cookies[this.TransIdCookieKey] != null ? Request.Cookies[this.TransIdCookieKey].Value : "0", out this.transId);
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            ReportsBO report = new ReportsBO(CurrentUserSession.NetSessionId);

            DataTable bets = null;
            try
            {
                bets = report.GetLastBetList(this.sportTypeGroup, this.betTypeGroup, this.transId, this.limitRowCount);                
            }
            catch (Exception ex)
            {
                if ((DateTime.Now - lastTimeWrittingExceptionLog).TotalSeconds >= MinTimeAllowToWriteLog)
                {
                    lastTimeWrittingExceptionLog = DateTime.Now;
                    Fanex.Logging.LogService.Critical(ex.Message, "Agent-LastBetMonitoring");
                }

                Response.Write(functionTurnOffError);
                Response.End();
            }

            int c = bets.Rows.Count;
            if (c > 0)
            {
                this.transId = Convert.ToInt64(bets.Rows[c - 1]["transid"]) - 1; // Get last top rows
            }

            HttpCookie cookie = new HttpCookie(this.TransIdCookieKey, this.transId.ToString());
            Response.Cookies.Set(cookie);

            return bets;
        }

        /// <summary>
        /// Creates the ticket data for Win/Place bet-types.
        /// </summary>
        /// <param name="ticket">The ticket.</param>
        /// <returns>Return tickets.</returns>
        private List<ITicketData> CreateWinPlaceTicketData(ITicket ticket)
        {
            if (winplaceBetTypesId.Contains(ticket.BetTypeId))
            {
                return new List<ITicketData> { 
                    new TicketData{// Win
                                    RefNo = ticket.RefNo,
                                    Status = ticket.Status,
                                    BetTeam = ticket.BetTeam,
                                    BetTypeId = ticket.BetTypeId == 33 ? 31 : 1231,
                                    Odds = ticket.Handicap1                           
                                  },
                    new TicketData{// Place
                                    RefNo = ticket.RefNo,   
                                    Status = ticket.Status,
                                    BetTypeId = ticket.BetTypeId == 33 ? 32 : 1232,
                                    Odds = ticket.Handicap2
                                  }
                };
            }

            return null;
        }


        /// <summary>
        /// Reading the status from config file.
        /// </summary>
        /// <returns>Return status.</returns>
        private bool CheckingLastsBetMonitoringFunctionStatus()
        {
            if (UserSession.Current.IsInternal)
            {
                return true;
            }

            var isEnableMonitoringBetsList = Converter.ToBool(System.Configuration.ConfigurationManager.AppSettings["EnableBetsListMonitoring"]);            
            if (isEnableMonitoringBetsList)
            {
                return true;
            }

            var usersAlwaysToAccessThisFunction = Converter.ToString2(System.Configuration.ConfigurationManager.AppSettings["UsersAlwaysAllowAccessBetsListMonitoring"]);
            if (string.IsNullOrEmpty(usersAlwaysToAccessThisFunction))
            {
                return false;
            }

            var customerIdArray = usersAlwaysToAccessThisFunction.Split(',');

            for (int i = 0; i < customerIdArray.Length; i++)
            {
                if(UserSession.Current.CustId == Converter.ToInt(customerIdArray[i]))
                {
                    return true;
                }
            }

            return false;
        }
    }
}